Running command: cd /workspace && cat > test_poc2.c << 'EOF'
#define _GNU_SOURCE
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

/* Forward declaration */
int fuzz_parse_http_request(const uint8_t *data, size_t length);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (len > 32767) len = 32767;

    uint8_t *data = malloc(len ? len : 1);
    fread(data, 1, len, f);
    fclose(f);

    fprintf(stderr, "Calling fuzz_parse_http_request with %ld bytes\n", len);
    int result = fuzz_parse_http_request(data, (size_t)len);
    fprintf(stderr, "Result: %d\n", result);

    free(data);
    return 0;
}
EOF
echo "test_poc2.c created"

